/**
 * 品牌字段归一：原始 brandName 为「无」或空、且 brandId 为空时，
 * 将 brandId 归一成前端约定的 'none'（对应选项「无」）。
 * 用于机构基本信息变更：保证 beforeForm（原值）与 form 都携带 'none'，
 * 避免品牌原始数据为「无」时，变更页原值角标显示「（空）」、字段回显为空。
 */
export function syncNoneBrand(form = {}) {
  if (!form || typeof form !== 'object') return form
  const { brandId, brandName } = form
  if (brandId != null && brandId !== '') return form
  const trimmedName = brandName != null ? String(brandName).trim() : ''
  if (!trimmedName || trimmedName === '无') {
    form.brandId = 'none'
    form.brandName = '无'
  }
  return form
}

